mapper.select:
select p.post_seq, p.category, p.title, p.view_count, p.recommend_count, p.comment_count, p.created_at, case when p.category = '익명' then '익명' else m.nickname end as writer_name from post p join member m on p.member_seq = m.member_seq where p.is_deleted = 'N'
and p.category = #{category}
order by p.post_seq desc
